import type { BankQuestion } from "@/lib/bank";

/** HR, Organisational Behaviour & Principles of Management (Management & Commerce): 200 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-hr-ob-1","question":"Which of these is NOT one of the core functions of management in the POSDC framework?","options":["Planning","Marketing","Staffing","Controlling"],"answer":1,"explanation":"POSDC stands for planning, organising, staffing, directing and controlling. Marketing is a business function, not a management function.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-2","question":"A machine operator gets conflicting instructions from both the production manager and the quality manager every day. Which of Fayol's principles is being violated?","options":["Unity of direction","Scalar chain","Unity of command","Division of work"],"answer":2,"explanation":"Unity of command says each employee should receive orders from only one superior. Unity of direction concerns one plan and one head for each group of activities with the same objective.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-3","question":"A factory engineer times each worker's movements with a stopwatch to find the single best way of doing every task and then trains all workers in it. Which approach is this?","options":["Human relations approach","Contingency approach","Bureaucratic management","Scientific management"],"answer":3,"explanation":"Time-and-motion study to find the 'one best way' is the core of F. W. Taylor's scientific management.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-4","question":"Two supervisors at the same level in different departments need to coordinate urgently. With their managers' permission, they talk directly instead of routing every message up and down the hierarchy. Which Fayol concept allows this?","options":["Esprit de corps","Unity of command","Gang plank","Centralisation"],"answer":2,"explanation":"The gang plank is a direct horizontal link between people at the same level, used with superiors' consent to avoid delays in the scalar chain.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-5","question":"A company has two separate marketing plans for the same product, each run by a different manager with different goals. Which of Fayol's principles is violated?","options":["Unity of command","Unity of direction","Equity","Order"],"answer":1,"explanation":"Unity of direction requires one head and one plan for a group of activities with the same objective. Here one objective has two plans and two heads.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-6","question":"A group CEO spends most of her time thinking about how the firm's businesses fit together and where the industry will be in ten years. According to Katz, which skill matters most for her role?","options":["Conceptual skill","Human skill","Technical skill","Clerical skill"],"answer":0,"explanation":"Katz argued that conceptual skills — seeing the organisation as a whole — matter most at the top, technical skills at the bottom and human skills at every level.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-7","question":"A plant head spends a week bargaining with the union over a new wage agreement. Which Mintzberg managerial role is she performing?","options":["Figurehead","Liaison","Monitor","Negotiator"],"answer":3,"explanation":"Negotiator is one of Mintzberg's decisional roles: representing the organisation in major negotiations. Figurehead and liaison are interpersonal roles; monitor is informational.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-8","question":"After a leadership meeting, a manager briefs her team on new priorities and passes on relevant facts. Which Mintzberg role is this?","options":["Entrepreneur","Spokesperson","Disseminator","Resource allocator"],"answer":2,"explanation":"The disseminator role passes information received from outside or above to members of one's own unit. The spokesperson role transmits information to outsiders.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-9","question":"In an organisation, every task is governed by written rules, positions form a clear hierarchy, decisions are impersonal and promotion depends on qualifications. This is closest to whose model?","options":["Mary Parker Follett's integration model","Elton Mayo's human relations model","Henri Fayol's administrative theory","Max Weber's bureaucracy"],"answer":3,"explanation":"Weber's ideal bureaucracy rests on rules, hierarchy, specialisation, impersonality, written records and merit-based careers.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-10","question":"Taylor's functional foremanship put eight specialist foremen over each worker. Which of Fayol's principles does this most directly conflict with?","options":["Unity of command","Division of work","Discipline","Remuneration"],"answer":0,"explanation":"With several foremen giving instructions, the worker has multiple bosses, which conflicts with unity of command.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-11","question":"Under Taylor's differential piece-rate system, the standard is 10 units a day. Workers who meet the standard earn ₹50 per unit; those below it earn ₹40 per unit. Worker A makes 12 units and Worker B makes 9. How much more does A earn than B in a day?","options":["₹150","₹240","₹200","₹120"],"answer":1,"explanation":"A = 12 × 50 = ₹600; B = 9 × 40 = ₹360; difference = ₹240. The higher rate rewards those who reach the standard, which was Taylor's aim.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-12","question":"A new manager stops the previous head's habit of playing team members against each other and instead builds team spirit and open communication. Which Fayol principle is she applying?","options":["Order","Centralisation","Esprit de corps","Scalar chain"],"answer":2,"explanation":"Esprit de corps means 'union is strength': managers should promote harmony and unity, not divide and rule.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-13","question":"A bank transfers its branch managers every few months, and staff turnover and errors rise sharply. Which Fayol principle has been neglected?","options":["Stability of tenure of personnel","Unity of direction","Equity","Initiative"],"answer":0,"explanation":"Fayol held that employees need time to learn their jobs; unnecessary turnover is both the cause and effect of poor management.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-14","question":"Match each Fayol principle with its description.\nA. Putting the right person and material in the right place\nB. Kindliness and justice in dealing with employees\nC. Encouraging employees to propose and carry out plans\nD. Putting the organisation's goals ahead of personal interests\n1. Equity  2. Order  3. Subordination of individual interest to general interest  4. Initiative","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-3, D-4"],"answer":1,"explanation":"Order = a place for everything and everyone; equity = kindliness and justice; initiative = freedom to think out and execute plans; and the general interest must prevail over individual interest.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-15","question":"A claims clerk refuses to process an urgent, valid insurance claim because the form was filled in blue ink instead of black, as the rulebook demands. Which weakness of bureaucracy does this show?","options":["Unity of command","Excessive decentralisation","Lack of specialisation","Goal displacement — following rules becomes an end in itself"],"answer":3,"explanation":"Rigid rule-following can replace the purpose the rules were meant to serve, a dysfunction often called goal displacement or 'red tape'.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-16","question":"In a set of factory experiments, output rose both when lighting was increased and when it was reduced, apparently because workers felt they were being noticed. These studies gave rise to which school of thought?","options":["Scientific management","Bureaucratic theory","Human relations movement","Quantitative management"],"answer":2,"explanation":"The Hawthorne studies, associated with Elton Mayo, showed that social factors and attention influence productivity, launching the human relations movement.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-17","question":"Which is the correct order of steps in the controlling process?","options":["Measure performance → set standards → take corrective action → compare","Set standards → measure performance → compare with standards → take corrective action","Compare with standards → set standards → measure performance → take corrective action","Set standards → take corrective action → measure performance → compare"],"answer":1,"explanation":"Controlling starts with standards, then measures actual performance, compares it with the standards and corrects significant deviations.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-18","question":"A plant manager tells supervisors: \"Don't send me every daily number. Report only when scrap goes above 3% or output falls 10% below plan.\" This is:","options":["Management by exception","Management by objectives","Feedforward control","Zero-based budgeting"],"answer":0,"explanation":"Management by exception reserves senior attention for significant deviations from plan, letting routine variances be handled lower down.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-19","question":"A food company tests every batch of incoming raw milk for quality before it enters the production line. This is an example of:","options":["Feedback control","Concurrent control","Bureaucratic control","Feedforward control"],"answer":3,"explanation":"Feedforward (preventive) control acts on inputs before the process starts. Concurrent control monitors during the process; feedback control examines results afterwards.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-20","question":"Assertion (A): Taylor's functional foremanship conflicts with Fayol's principle of unity of command.\nReason (R): Under functional foremanship, a worker takes instructions from several specialist foremen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Unity of command means one boss per worker. Several specialist foremen means several bosses, so R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-21","question":"Consider these statements comparing Fayol and Taylor:\nI. Fayol looked at management from the top level; Taylor focused on the shop floor.\nII. Fayol offered general principles of administration; Taylor stressed scientific study of tasks.\nIII. Both rejected the use of incentive pay.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"I and II are correct. III is false: Taylor strongly favoured incentive pay through the differential piece-rate system.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-22","question":"A consultant tells a client: \"There is no single best way to organise. The right structure depends on your technology, environment and size.\" Which school of management does this reflect?","options":["Classical approach","Contingency approach","Scientific management","Bureaucratic approach"],"answer":1,"explanation":"The contingency (situational) approach holds that effective practice depends on the circumstances, rejecting universal 'one best way' prescriptions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-23","question":"Taylor argued that managers and workers should stop fighting over how to divide the surplus and instead cooperate to increase it. He called this:","options":["Functional foremanship","Scientific selection of workers","Mental revolution","Management by exception"],"answer":2,"explanation":"Taylor's 'mental revolution' was a change of attitude on both sides — from conflict over shares to cooperation in enlarging the total surplus.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-24","question":"A company has 4,096 front-line workers. How many managers (at all levels above the workers) does it need with a uniform span of control of 8, compared with a span of 4?","options":["4 vs 6","512 vs 1,024","585 vs 1,024","585 vs 1,365"],"answer":3,"explanation":"Span 8: 512 + 64 + 8 + 1 = 585 managers in 4 levels. Span 4: 1,024 + 256 + 64 + 16 + 4 + 1 = 1,365 managers in 6 levels. Doubling the span saves 780 managers and two levels.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-25","question":"Match each plan with an example.\nA. Policy  B. Procedure  C. Rule  D. Budget\n1. The step-by-step method for claiming travel reimbursement\n2. A plan stated in numbers for a period\n3. \"We prefer to fill vacancies by promoting from within\"\n4. \"Smoking is not allowed on the factory floor\"","options":["A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2","A-3, B-2, C-4, D-1","A-1, B-3, C-4, D-2"],"answer":0,"explanation":"A policy guides thinking and leaves discretion; a procedure sets the sequence of steps; a rule says what must or must not be done, with no discretion; a budget is a plan in numbers.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-26","question":"A company draws up a one-time plan to build and commission a new plant within 18 months. This is best classified as a:","options":["Standing plan","Policy","Single-use plan","Rule"],"answer":2,"explanation":"Single-use plans (programmes, projects, budgets) are made for a specific, non-recurring purpose. Standing plans such as policies, procedures and rules are used repeatedly.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-27","question":"What is the distinguishing feature of Management by Objectives (MBO)?","options":["Top management sets objectives and passes them down unchanged","Superior and subordinate jointly set specific objectives and later review performance against them","Employees choose their own goals without managerial input","Performance is judged only on personal traits"],"answer":1,"explanation":"MBO, popularised by Peter Drucker, relies on joint goal setting, periodic review and appraisal against agreed objectives.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-28","question":"Which of these goals best meets the SMART criteria?","options":["Improve customer satisfaction soon","Work harder on new accounts this year","Be the best sales team in the country","Raise repeat-purchase rate in the South zone from 30% to 36% by 31 March"],"answer":3,"explanation":"The second goal is specific, measurable, achievable, relevant and time-bound. The others lack a measure, a deadline or both.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-29","question":"Consider these reasons why an MBO programme might fail:\nI. Objectives are imposed from above with no real participation.\nII. Focus on short-term measurable goals crowds out long-term ones.\nIII. MBO needs no periodic progress reviews.\nWhich are valid reasons for failure?","options":["I and II only","I, II and III","II and III only","III only"],"answer":0,"explanation":"I and II are well-known pitfalls. III is false as a statement about MBO: periodic review is an essential part of it, and skipping reviews is itself a cause of failure.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-30","question":"A mid-sized manufacturer groups its staff into production, finance, marketing and HR departments, each headed by a specialist. What structure is this?","options":["Divisional structure","Network structure","Matrix structure","Functional structure"],"answer":3,"explanation":"A functional structure groups jobs by specialist activity. It is efficient for a single product line but can create silos.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-31","question":"When a manager delegates a task to a subordinate, which of these does the manager still keep?","options":["The authority to do the task","Ultimate accountability for the result","The work itself","Nothing — everything is transferred"],"answer":1,"explanation":"Authority can be delegated, but the delegator remains ultimately accountable to their own superior for the outcome.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-32","question":"News of an upcoming reorganisation spreads through an office via informal chats long before any official announcement. This informal communication network is called the:","options":["Scalar chain","Formal channel","Gang plank","Grapevine"],"answer":3,"explanation":"The grapevine is the informal communication network. It is fast and often partly accurate, and managers can use it as well as fight rumours.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-33","question":"A company runs three unrelated businesses — paints, packaged foods and insurance — and each has its own production, marketing and finance teams under a business head. What structure is this?","options":["Functional","Matrix","Divisional","Line"],"answer":2,"explanation":"A divisional structure creates self-contained units by product, region or customer. It improves focus and accountability but duplicates functions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-34","question":"Engineers in an infrastructure firm report to their functional head for technical standards and to a project manager for day-to-day project work. What structure is this?","options":["Functional","Divisional","Network","Matrix"],"answer":3,"explanation":"A matrix structure combines functional and project (or product) lines, so employees have two bosses.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-35","question":"A company widens the average span of control from 5 to 12 subordinates per manager. What is the most likely effect on its structure?","options":["It becomes taller with more levels","It becomes flatter with fewer levels","Its number of levels stays the same","It becomes more centralised"],"answer":1,"explanation":"A wider span means fewer managers are needed at each level, so the hierarchy becomes flatter.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-36","question":"Which situation calls for a narrow span of control?","options":["Subordinates do routine, standardised work","Subordinates are highly skilled and experienced","Work is complex and novel and needs close guidance","Good information systems and clear procedures exist"],"answer":2,"explanation":"Complex, changing work and inexperienced staff need close supervision, so spans are narrower. The other three conditions allow wider spans.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-37","question":"An HR specialist advises the production manager on how to handle a disciplinary case, but the production manager makes the final decision. The HR specialist is exercising:","options":["Staff authority","Line authority","Functional authority","Charismatic authority"],"answer":0,"explanation":"Staff authority is advisory: specialists recommend, while line managers in the chain of command decide.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-38","question":"A purchase manager stops evaluating suppliers as soon as she finds one that meets the minimum requirements on price and quality, rather than searching for the best possible supplier. This is:","options":["Optimising","Groupthink","Escalation of commitment","Satisficing under bounded rationality"],"answer":3,"explanation":"Herbert Simon argued that limited time and information lead decision makers to 'satisfice' — accept the first acceptable option — rather than optimise.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-39","question":"A highly cohesive top team rushes to approve an acquisition. Members who have doubts stay silent, and warning signs are dismissed. What is happening and what is a good remedy?","options":["Social loafing — assign individual tasks","Escalation of commitment — set a stop-loss rule","Groupthink — appoint a devil's advocate and invite outside views","Anchoring — use a different starting figure"],"answer":2,"explanation":"Groupthink is the pressure for agreement in cohesive groups that suppresses dissent. Devil's advocates, outside experts and leaders withholding their own view early help counter it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-40","question":"A firm sends a forecasting questionnaire to experts who never meet. Their anonymous answers are summarised and sent back for several rounds until views converge. This is the:","options":["Nominal group technique","Delphi technique","Brainstorming","Devil's advocacy"],"answer":1,"explanation":"The Delphi technique uses anonymous, iterative rounds of expert input with controlled feedback, avoiding the influence of dominant personalities.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-41","question":"In a meeting, each member first writes down ideas silently, then the ideas are shared one by one without discussion, discussed briefly and finally ranked by private vote. This is the:","options":["Nominal group technique","Delphi technique","Brainstorming","Electronic meeting"],"answer":0,"explanation":"The nominal group technique keeps members together but structures the process so that everyone contributes independently before discussion and voting.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-42","question":"A store system automatically reorders a product whenever stock falls below 200 units. This is an example of a:","options":["Non-programmed decision","Decision under uncertainty","Strategic decision","Programmed decision"],"answer":3,"explanation":"Programmed decisions are routine and repetitive and can be handled by fixed rules. Non-programmed decisions are novel and unstructured.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-43","question":"A manager keeps pouring money into a failing software project, arguing that \"we have already spent ₹2 crore — we can't stop now.\" This is:","options":["Escalation of commitment (sunk-cost trap)","Anchoring bias","Availability bias","Confirmation bias"],"answer":0,"explanation":"Escalation of commitment is sticking with a losing course because of past investment. Sunk costs should be ignored; only future costs and benefits matter.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-44","question":"In a salary negotiation, the candidate opens with a high figure, and the final offer ends up much higher than the employer originally planned. Which bias most likely influenced the employer?","options":["Hindsight bias","Halo effect","Anchoring","Overconfidence"],"answer":2,"explanation":"Anchoring is relying too heavily on the first number offered; later adjustments stay close to that anchor.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-45","question":"Consider these statements about the matrix structure:\nI. Dual reporting can create role ambiguity and conflict.\nII. It allows specialist staff to be shared across projects.\nIII. It removes power struggles between functional and project managers.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. III is false: power struggles between the two lines of authority are a classic matrix problem.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-46","question":"A firm can launch a product itself (60% chance of ₹50 lakh profit, 40% chance of a ₹20 lakh loss) or license it for a guaranteed ₹18 lakh. Using expected monetary value, what should it do?","options":["License, because the launch EMV is ₹15 lakh","License, because ₹18 lakh is certain","Launch, because its EMV is ₹30 lakh","Launch, because its EMV is ₹22 lakh"],"answer":3,"explanation":"EMV of launching = 0.6 × 50 − 0.4 × 20 = 30 − 8 = ₹22 lakh, which beats ₹18 lakh. ₹30 lakh ignores the possible loss. A risk-averse firm might still license, but EMV favours launching.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-47","question":"For the same choice (launch: 60% chance of +₹50 lakh, 40% chance of −₹20 lakh; license: certain ₹18 lakh), what is the expected value of perfect information about whether the launch will succeed?","options":["₹4 lakh","₹15.2 lakh","₹37.2 lakh","₹7.2 lakh"],"answer":1,"explanation":"With perfect information the firm launches if success is coming (₹50 lakh) and licenses otherwise (₹18 lakh): 0.6 × 50 + 0.4 × 18 = ₹37.2 lakh. The best choice without information is worth ₹22 lakh, so EVPI = ₹15.2 lakh.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-48","question":"Assertion (A): A retail chain operating in very different regional markets often lets regional heads decide pricing and product range.\nReason (R): Decentralisation places decisions closer to the people with local market information.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"When markets differ, local knowledge matters more than uniformity, so decentralised decisions are faster and better informed — R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-49","question":"A sportswear company designs products and manages its brand in-house but outsources manufacturing, logistics and customer support to partner firms. This is best described as a:","options":["Functional structure","Tall structure","Network (virtual) structure","Matrix structure"],"answer":2,"explanation":"A network structure keeps a small core that coordinates independent partners performing other functions under contract.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-50","question":"According to Burns and Stalker, which type of structure suits a firm in a fast-changing, uncertain environment such as consumer technology?","options":["Organic: flexible roles, lateral communication, decentralised decisions","Mechanistic: rigid rules, narrow roles, vertical communication","Bureaucratic: strict hierarchy and written procedures","Functional: strict departmental boundaries"],"answer":0,"explanation":"Organic structures adapt quickly to change. Mechanistic structures work in stable, predictable environments.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-51","question":"Graicunas showed that the possible relationships between a manager and n subordinates equal n(2ⁿ⁻¹ + n − 1). How many relationships are there with 5 subordinates?","options":["25","100","44","20"],"answer":1,"explanation":"5 × (2⁴ + 5 − 1) = 5 × 20 = 100. The number grows far faster than the number of subordinates, which was Graicunas' argument for limiting the span.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-52","question":"Consider these statements about delegation:\nI. Authority delegated should match the responsibility assigned.\nII. Delegation reduces the delegator's own accountability.\nIII. Delegation helps develop subordinates for bigger roles.\nWhich are correct?","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"I (parity of authority and responsibility) and III are correct. II is false: accountability cannot be delegated.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-53","question":"Match each structure with its defining feature.\nA. Functional  B. Divisional  C. Matrix  D. Network\n1. Employees report to two managers\n2. Grouping by specialist activity\n3. Self-contained units by product or region\n4. A small core firm coordinating outside partners","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Functional = specialist grouping; divisional = self-contained units; matrix = dual reporting; network = coordinating outsourced partners.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-54","question":"Payoffs (₹ lakh) for three strategies under high and low demand are: S1 — 80 and 10; S2 — 60 and 30; S3 — 40 and 35. Which strategy does the minimax-regret criterion choose?","options":["S1","S2","S3","S1 and S3 tie"],"answer":1,"explanation":"Regret = best payoff in that state − payoff. High demand (best 80): S1 0, S2 20, S3 40. Low demand (best 35): S1 25, S2 5, S3 0. Maximum regrets: S1 25, S2 20, S3 40. The smallest maximum regret is S2.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-55","question":"Using the same payoffs (S1 — 80 high / 10 low; S2 — 60 / 30; S3 — 40 / 35), which strategy does a pessimistic decision maker using the maximin criterion choose?","options":["S1","S2","S3","Any of them"],"answer":2,"explanation":"Maximin picks the best of the worst outcomes: worst payoffs are 10, 30 and 35, so S3. An optimist (maximax) would choose S1.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-56","question":"A bank organises itself into separate retail banking, corporate banking and rural banking divisions, each serving a different type of client. This is departmentation by:","options":["Function","Product","Customer","Process"],"answer":2,"explanation":"Grouping activities around different client types is customer departmentation.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-57","question":"Which of these practices violates the basic rules of brainstorming?","options":["Encouraging wild ideas","Evaluating and criticising each idea as soon as it is proposed","Aiming for a large number of ideas","Building on other people's ideas"],"answer":1,"explanation":"Brainstorming separates idea generation from evaluation. Criticism during generation discourages people from contributing.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-58","question":"In a retail chain, every purchase above ₹5,000 at any store needs approval from head office. This indicates a high degree of:","options":["Centralisation","Decentralisation","Delegation","Departmentation"],"answer":0,"explanation":"Centralisation means decision-making authority is kept at the top of the organisation.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-59","question":"After a round of layoffs, a team member says his biggest concern is whether his own job will still exist next year. In Maslow's hierarchy, which need is most active?","options":["Physiological","Esteem","Safety","Self-actualisation"],"answer":2,"explanation":"Job security and protection from threats belong to safety needs, the second level of Maslow's hierarchy.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-60","question":"A manager believes employees naturally dislike work, avoid responsibility and must be closely supervised and threatened with penalties. This matches:","options":["Maslow's self-actualisation","McGregor's Theory Y","Herzberg's motivators","McGregor's Theory X"],"answer":3,"explanation":"Theory X assumes people are lazy and need control; Theory Y assumes people can enjoy work, seek responsibility and exercise self-direction.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-61","question":"Which of these is a 'motivator' rather than a 'hygiene factor' in Herzberg's two-factor theory?","options":["Salary","Recognition for achievement","Company policy","Working conditions"],"answer":1,"explanation":"Motivators are intrinsic to the job: achievement, recognition, the work itself, responsibility and growth. Salary, policy and conditions are hygiene factors.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-62","question":"A production head pushes hard for output targets but shows little concern for his team's wellbeing. Where does he sit on the Blake–Mouton managerial grid?","options":["1,1 Impoverished","1,9 Country club","9,1 Authority-compliance","9,9 Team management"],"answer":2,"explanation":"The grid's first number is concern for production and the second is concern for people. 9,1 is high production, low people — authority-compliance (task) management.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-63","question":"A team leader keeps everyone happy and avoids any pressure, even when deadlines slip badly. On the Blake–Mouton grid this is:","options":["9,1 Authority-compliance","5,5 Middle of the road","1,9 Country club","1,1 Impoverished"],"answer":2,"explanation":"1,9 country-club management shows high concern for people and low concern for production.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-64","question":"A newly hired analyst lacks the skills for a task and feels anxious and unsure. According to Hersey and Blanchard, which leadership style fits best?","options":["Telling (S1)","Selling (S2)","Participating (S3)","Delegating (S4)"],"answer":0,"explanation":"A follower who is unable and unwilling or insecure (R1) needs telling: clear, specific instructions and close supervision.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-65","question":"A senior engineer is highly skilled, confident and eager to own a project. Under Hersey–Blanchard's situational model, the manager should mainly use:","options":["Telling","Delegating","Participating","Selling"],"answer":1,"explanation":"An able and willing (R4) follower needs little direction or support, so delegating — handing over responsibility — fits.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-66","question":"A sales executive prefers moderately difficult targets, wants frequent feedback on her performance and likes to take personal responsibility for results. Which need dominates, per McClelland?","options":["Need for security","Need for affiliation","Need for power","Need for achievement"],"answer":3,"explanation":"High-nAch people seek moderate-risk goals, quick feedback and personal responsibility for outcomes.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-67","question":"A manager sets clear targets, rewards people who meet them and steps in only when performance goes off track. This style is best described as:","options":["Transformational leadership","Laissez-faire leadership","Transactional leadership","Servant leadership"],"answer":2,"explanation":"Transactional leadership relies on contingent rewards and management by exception. Transformational leadership inspires through vision and personal development.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-68","question":"An experienced, skilled manager has lost confidence after a reorganisation changed her role. Under Hersey–Blanchard's model, which style should her boss use?","options":["Telling","Participating","Selling","Delegating"],"answer":1,"explanation":"She is able but insecure (R3), so she needs low direction and high support — participating, with shared decisions and encouragement.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-69","question":"A top performer is told that hitting next year's target will earn her a promotion to the Delhi office. She is confident she can hit the target and trusts the promise, but she has no wish to relocate. Her motivation to try is very low. In Vroom's terms, which factor is close to zero?","options":["Valence","Instrumentality","Expectancy","Equity"],"answer":0,"explanation":"Valence is the value placed on the reward. Because motivation = E × I × V, a near-zero valence makes motivation near zero even when expectancy and instrumentality are high.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-70","question":"An employee rates two assignments using Vroom's model. Assignment A: expectancy 0.9, instrumentality 0.6, valence 5. Assignment B: expectancy 0.5, instrumentality 0.9, valence 8. Which will she be more motivated to pursue?","options":["A, with a score of 2.7","They are equal","A, with a score of 4.5","B, with a score of 3.6"],"answer":3,"explanation":"A = 0.9 × 0.6 × 5 = 2.7; B = 0.5 × 0.9 × 8 = 3.6. B wins despite its lower expectancy because the reward is valued more highly.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-71","question":"An analyst discovers that a colleague doing the same work with similar experience earns 20% more. According to Adams' equity theory, which response is most likely?","options":["She will work harder to justify her lower pay","She will feel over-rewarded and guilty","She may reduce her effort, ask for a raise or start looking for another job","She will be unaffected because pay is a hygiene factor"],"answer":2,"explanation":"Perceived under-reward creates tension that people reduce by cutting inputs, seeking higher outcomes, changing the comparison or leaving.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-72","question":"Employee A earns ₹60,000 a month for 50 hours a week. His referent, B, earns ₹72,000 for 48 hours. To restore equity on a pay-per-hour basis without changing his hours, what should A earn?","options":["₹72,000","₹62,500","₹69,120","₹75,000"],"answer":3,"explanation":"B's ratio = 72,000 / 48 = ₹1,500 per hour. A's ratio is 60,000 / 50 = ₹1,200. At 50 hours, equity needs 50 × 1,500 = ₹75,000. Matching B's pay (₹72,000) ignores that A works longer.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-73","question":"A company raises salaries, improves the canteen and relaxes rigid policies. Complaints drop sharply, but employees show no extra enthusiasm or initiative. What best explains this according to Herzberg?","options":["The changes improved hygiene factors, which reduce dissatisfaction but do not create motivation","The changes improved motivators, which take time to work","Employees are Theory X types","The changes created inequity"],"answer":0,"explanation":"Hygiene factors prevent dissatisfaction; to motivate, the firm must enrich the job itself with responsibility, achievement, recognition and growth.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-74","question":"According to Locke's goal-setting theory, which instruction is most likely to raise a sales rep's performance?","options":["\"Do your best this quarter.\"","\"Increase client meetings from 40 to 50 a week; we'll review your numbers every Friday.\"","\"Try not to fall behind last year.\"","\"Make as many calls as you comfortably can.\""],"answer":1,"explanation":"Specific, challenging goals that the person accepts, combined with regular feedback, lead to higher performance than vague 'do your best' goals.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-75","question":"Consider these statements about Fiedler's contingency model:\nI. It treats a leader's style as relatively fixed.\nII. Task-oriented (low-LPC) leaders do best when situational control is either very high or very low.\nIII. It recommends that leaders simply change their style to suit each situation.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. Because Fiedler sees style as fixed, he suggests changing the situation or the leader, not the style — so III is false.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-76","question":"A new team faces vague, unstructured tasks and members are unsure what is expected. According to House's path–goal theory, which leader behaviour is likely to be most effective?","options":["Directive leadership — clarify goals, methods and schedules","Supportive leadership only","Laissez-faire leadership","Achievement-oriented leadership with stretch goals only"],"answer":0,"explanation":"Path–goal theory says directive behaviour helps when tasks are ambiguous; it is less useful (even resented) when tasks are already clear and routine.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-77","question":"A department head meets each team member regularly, understands their individual career goals and coaches them accordingly. Which component of transformational leadership is this?","options":["Idealised influence","Individualised consideration","Intellectual stimulation","Inspirational motivation"],"answer":1,"explanation":"Individualised consideration means attending to each follower's needs and acting as coach or mentor.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-78","question":"Match each transformational-leadership component with a behaviour.\nA. Idealised influence  B. Inspirational motivation  C. Intellectual stimulation  D. Individualised consideration\n1. Encourages the team to question assumptions and try new approaches\n2. Acts as a role model with high ethical standards\n3. Communicates an exciting vision and high expectations\n4. Coaches each person according to their needs","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Idealised influence = role model; inspirational motivation = vision; intellectual stimulation = challenging assumptions; individualised consideration = coaching.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-79","question":"An employee repeatedly passed over for promotion stops seeking growth and instead becomes focused on pay rises and office friendships. Which theory explains this best?","options":["Maslow's strict hierarchy","Herzberg's two-factor theory","Alderfer's ERG theory (frustration–regression)","Adams' equity theory"],"answer":2,"explanation":"Alderfer's ERG theory adds frustration–regression: when growth needs are blocked, people regress to lower needs such as relatedness and existence.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-80","question":"Assertion (A): For an employee who is already fairly paid, a further pay rise may not increase motivation in Herzberg's view.\nReason (R): Herzberg classed pay as a hygiene factor, whose improvement removes dissatisfaction but does not create satisfaction.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Once pay is adequate, more pay mainly prevents dissatisfaction; motivation comes from motivators. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-81","question":"Consider these statements about McClelland's needs theory:\nI. People high in need for achievement prefer very high-risk goals.\nII. Effective senior managers often show a high need for institutional (socialised) power and relatively low need for affiliation.\nIII. People with a very high need for affiliation may avoid tough decisions that upset colleagues.\nWhich are correct?","options":["I only","I, II and III","I and II only","II and III only"],"answer":3,"explanation":"II and III are correct. High achievers prefer moderate risk where their effort makes the difference, so I is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-82","question":"Using Vroom's model (motivation = E × I × V, each on a 0–1 scale), which combination gives the highest motivation?","options":["E 0.9, I 0.9, V 0.2","E 0.6, I 0.6, V 0.6","E 1.0, I 0, V 1.0","E 0.5, I 0.8, V 0.7"],"answer":3,"explanation":"Products: 0.162, 0.216, 0 and 0.28. The last is highest. Because the terms multiply, a single weak factor drags the whole score down.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-83","question":"Match each employee's statement with the Vroom component that is weak.\nA. \"However hard I try, I can't hit that target with the leads I get.\"\nB. \"Even if I hit it, the bonus never actually gets paid.\"\nC. \"The reward is a gift voucher — I don't care about it.\"\n1. Instrumentality  2. Valence  3. Expectancy","options":["A-3, B-1, C-2","A-1, B-3, C-2","A-3, B-2, C-1","A-2, B-1, C-3"],"answer":0,"explanation":"Expectancy links effort to performance, instrumentality links performance to reward, and valence is how much the reward is valued.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-84","question":"In Hersey and Blanchard's model, which style combines high relationship behaviour with low task behaviour?","options":["Telling","Participating","Selling","Delegating"],"answer":1,"explanation":"Telling = high task, low relationship; selling = high task, high relationship; participating = low task, high relationship; delegating = low on both.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-85","question":"What is the main criticism of the trait approach to leadership?","options":["It ignores leaders' personal qualities","It focuses only on followers","No consistent set of traits reliably predicts leadership effectiveness across situations","It requires leaders to change their style frequently"],"answer":2,"explanation":"Research found that traits linked to leadership in one setting often did not hold in others, which led to behavioural and situational theories.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-86","question":"The head of a research lab gives highly qualified scientists complete freedom to choose projects and methods, offering little direction or feedback. This is:","options":["Autocratic leadership","Laissez-faire (free-rein) leadership","Transactional leadership","Paternalistic leadership"],"answer":1,"explanation":"Laissez-faire leaders leave decisions to the group. It can work with expert, self-motivated teams but often fails with less experienced staff.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-87","question":"A supervisor defines each team member's role, sets deadlines and specifies procedures. In the Ohio State studies, this behaviour is called:","options":["Initiating structure","Consideration","Employee orientation","Charisma"],"answer":0,"explanation":"The Ohio State studies identified two dimensions: initiating structure (organising tasks and roles) and consideration (trust, respect and concern for followers).","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-88","question":"A newly formed project team argues openly about who should lead, how work should be split and whose ideas matter most. In Tuckman's model, which stage is this?","options":["Forming","Performing","Norming","Storming"],"answer":3,"explanation":"Storming is marked by conflict over roles, leadership and direction. Forming is the polite, uncertain start; norming builds agreed rules and cohesion.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-89","question":"An employee is organised, dependable, careful and always meets deadlines. Which Big Five trait does this describe?","options":["Openness to experience","Extraversion","Conscientiousness","Agreeableness"],"answer":2,"explanation":"Conscientiousness covers being organised, responsible, persistent and achievement-oriented.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-90","question":"In Lewin's three-step model of change, what is the first step?","options":["Refreezing","Moving","Anchoring","Unfreezing"],"answer":3,"explanation":"Lewin's steps are unfreezing (preparing people to let go of the old way), moving (making the change) and refreezing (making it stick).","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-91","question":"An interviewer is so impressed by a candidate's prestigious college that she also rates his teamwork and communication as excellent, without evidence. This is the:","options":["Contrast effect","Halo effect","Projection","Central tendency"],"answer":1,"explanation":"The halo effect is letting one positive characteristic shape the overall impression. The opposite (one negative trait colouring everything) is the horns effect.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-92","question":"Faced with a dispute between two team members, a manager keeps postponing any discussion in the hope that it will fade away. Which Thomas–Kilmann conflict style is this?","options":["Accommodating","Avoiding","Compromising","Competing"],"answer":1,"explanation":"Avoiding is low on both assertiveness and cooperativeness: the issue is sidestepped or postponed.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-93","question":"A manager gives in to a colleague's preference on a minor scheduling issue, mainly to preserve their good relationship. Which conflict style is this?","options":["Competing","Avoiding","Collaborating","Accommodating"],"answer":3,"explanation":"Accommodating is cooperative but unassertive — putting the other party's concerns first, often when the issue matters more to them or harmony is important.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-94","question":"In a group assignment where only the final report is graded, some members contribute much less effort than when they work alone. This is known as:","options":["Groupthink","Group polarisation","Social loafing","Social facilitation"],"answer":2,"explanation":"Social loafing is reduced effort in groups when individual contributions cannot be identified. Making individual work visible and accountable reduces it.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-95","question":"A visitor notices a company's open-plan office, casual dress and a wall of team photos. In Schein's model of culture, these are examples of:","options":["Artefacts","Espoused values","Basic underlying assumptions","Subcultures"],"answer":0,"explanation":"Artefacts are the visible, surface level of culture — structures, dress, rituals, layouts. Their deeper meaning lies in espoused values and basic assumptions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-96","question":"According to Kotter's eight-step model, what should a leader do first when launching a major change?","options":["Form a guiding coalition","Create a sense of urgency","Generate short-term wins","Anchor the change in the culture"],"answer":1,"explanation":"Kotter's model starts by establishing urgency — showing why change is needed now — before building a coalition and vision.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-97","question":"An employee believes his career success depends mainly on luck and on who the boss likes, not on his own effort. He has:","options":["An external locus of control","An internal locus of control","High self-efficacy","High Machiavellianism"],"answer":0,"explanation":"People with an external locus of control attribute outcomes to outside forces such as luck or others; those with an internal locus credit their own actions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-98","question":"Ravi is late to every team meeting (high consistency), is also late for client calls and training (low distinctiveness), while his colleagues are rarely late (low consensus). According to Kelley's attribution theory, his manager will most likely attribute the lateness to:","options":["External causes such as traffic","Bad luck","The meeting schedule","Internal causes such as Ravi's own habits"],"answer":3,"explanation":"High consistency, low distinctiveness and low consensus together point to an internal (personal) cause.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-99","question":"On one particular day, almost everyone in the office arrives late (high consensus). Priya, who arrived late too, is usually punctual everywhere (low consistency) and is not generally late for other things (high distinctiveness). Her lateness is most likely to be attributed to:","options":["Internal causes","Her personality","External causes","Her lack of motivation"],"answer":2,"explanation":"High consensus, high distinctiveness and low consistency point to an external cause, such as a transport strike.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-100","question":"A sales head blames a rep's missed target on laziness, ignoring the fact that the rep's territory lost its largest customer to a plant closure. This illustrates the:","options":["Self-serving bias","Fundamental attribution error","Contrast effect","Similar-to-me error"],"answer":1,"explanation":"The fundamental attribution error is overestimating personal factors and underestimating situational factors when judging others' behaviour.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-101","question":"A manager credits his own strategy when sales rise but blames 'market conditions' when sales fall. This is:","options":["Fundamental attribution error","Halo effect","Self-serving bias","Stereotyping"],"answer":2,"explanation":"The self-serving bias attributes our own successes to internal factors and our failures to external ones.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-102","question":"Two department heads disagree on a new product's design. Both concerns are important, the issue is complex and there is time to work through it. Which conflict style is most appropriate?","options":["Competing","Compromising","Avoiding","Collaborating"],"answer":3,"explanation":"Collaborating — high assertiveness and high cooperativeness — seeks a solution that fully satisfies both sides. It needs time and trust, which are available here.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-103","question":"Two managers of equal power must agree on a shared budget before tomorrow's deadline. Both goals are moderately important, and each agrees to give up part of what they wanted. This is:","options":["Compromising","Collaborating","Accommodating","Competing"],"answer":0,"explanation":"Compromising finds a middle ground under time pressure or when power is balanced; each side gets part, not all, of what it wanted.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-104","question":"A plant manager immediately orders a production line shut down after a safety hazard is found, despite protests from the shift team about lost output. Which conflict style is appropriate here, and why?","options":["Accommodating — to keep the team happy","Competing — quick, decisive action is needed on a vital issue","Avoiding — to let tempers cool","Compromising — run the line at half speed"],"answer":1,"explanation":"Competing (assertive, uncooperative) suits emergencies and unpopular but vital decisions such as safety actions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-105","question":"Before introducing new software, a manager lists forces pushing for it (faster reporting, client demands) and forces against it (fear of job loss, training time), and plans to strengthen the first and weaken the second. This tool is:","options":["SWOT analysis","PEST analysis","Johari window","Force-field analysis"],"answer":3,"explanation":"Lewin's force-field analysis compares driving and restraining forces; change happens when driving forces outweigh restraining ones. Reducing restraints often causes less tension than adding pressure.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-106","question":"A change team realises it lacks full information about shop-floor processes, and supervisors who could block the change hold considerable informal power. According to Kotter and Schlesinger, which approach to resistance fits best?","options":["Coercion","Manipulation and co-optation","Participation and involvement","Ignoring the resistance"],"answer":2,"explanation":"Participation works when initiators lack information and resisters have power: involving them improves the design and builds commitment, though it takes time.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-107","question":"Consider these statements about Kelley's attribution theory:\nI. High consensus points towards an external cause.\nII. High consistency points towards an internal cause.\nIII. High distinctiveness points towards an internal cause.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"I and II are correct. High distinctiveness — the person behaves differently in other situations — points towards an external cause, so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-108","question":"Arrange these steps from Kotter's model in the correct order:\nP. Generate short-term wins\nQ. Form a powerful guiding coalition\nR. Anchor new approaches in the culture\nS. Establish a sense of urgency","options":["Q → S → P → R","S → Q → P → R","S → P → Q → R","S → Q → R → P"],"answer":1,"explanation":"Kotter's sequence: urgency, guiding coalition, vision and strategy, communicating the vision, empowering action, short-term wins, consolidating gains and finally anchoring change in the culture.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-109","question":"Which Big Five trait has been found to be the most consistent predictor of job performance across a wide range of occupations?","options":["Conscientiousness","Openness to experience","Extraversion","Agreeableness"],"answer":0,"explanation":"Conscientiousness relates to performance in almost all jobs. Extraversion predicts success mainly in sales and management roles.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-110","question":"A team leader receives harsh criticism from a client in a meeting, feels angry, but stays calm, thinks before responding and discusses the issue constructively. Which component of emotional intelligence (Goleman) is she showing?","options":["Self-awareness","Social skill","Empathy","Self-regulation"],"answer":3,"explanation":"Self-regulation is controlling disruptive impulses and moods and thinking before acting. Self-awareness is recognising one's emotions in the first place.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-111","question":"In the Johari window, which area contains things others know about a person but the person does not know about themselves, and what shrinks it?","options":["Hidden area — self-disclosure","Unknown area — self-discovery","Blind area — feedback from others","Open area — feedback from others"],"answer":2,"explanation":"The blind area is known to others but not to oneself. Seeking and accepting feedback reduces it; self-disclosure reduces the hidden area.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-112","question":"Assertion (A): A newly formed team that avoids openly discussing disagreements may slip back into conflict later.\nReason (R): Teams that do not work through storming-stage issues struggle to develop the shared norms needed for high performance.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Unresolved conflict over roles and goals stays beneath the surface and resurfaces; agreed norms come from working through storming. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-113","question":"Match each Thomas–Kilmann style with its position on assertiveness and cooperativeness.\nA. Competing  B. Accommodating  C. Avoiding  D. Collaborating\n1. High assertiveness, high cooperativeness\n2. Low assertiveness, low cooperativeness\n3. High assertiveness, low cooperativeness\n4. Low assertiveness, high cooperativeness","options":["A-1, B-4, C-2, D-3","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Competing = assertive and uncooperative; accommodating = cooperative and unassertive; avoiding = neither; collaborating = both. Compromising sits in the middle.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-114","question":"A young start-up prizes experimentation, risk-taking and launching new ideas quickly, with an external focus and flexible structure. In the competing values framework, which culture type is this?","options":["Clan","Market","Adhocracy","Hierarchy"],"answer":2,"explanation":"Adhocracy culture combines flexibility with an external focus and values innovation. Clan is flexible but internally focused; market is controlled and externally focused; hierarchy is controlled and internally focused.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-115","question":"Consider these statements about Hofstede's cultural dimensions:\nI. High uncertainty-avoidance cultures prefer clear rules and structured situations.\nII. Individualist cultures put loyalty to the group ahead of personal goals.\nIII. Long-term orientation values perseverance and thrift.\nWhich are correct?","options":["I, II and III","I and III only","I and II only","II and III only"],"answer":1,"explanation":"I and III are correct. II describes collectivism; individualist cultures emphasise personal goals and self-reliance.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-116","question":"A document lists the qualifications, experience, skills and personal qualities a person needs to do a job. This document is the:","options":["Job description","Job specification","Job evaluation","Job enrichment plan"],"answer":1,"explanation":"The job specification describes the person (qualifications, skills, traits). The job description describes the job (duties, tasks, responsibilities). Both come from job analysis.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-117","question":"Which of these is an internal source of recruitment?","options":["Campus placement","Placement agency","Newspaper advertisement","Internal job posting for current employees"],"answer":3,"explanation":"Internal job posting fills vacancies from existing staff. Campus drives, advertisements and agencies bring in outside candidates.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-118","question":"At the end of a workshop, participants fill in a form rating how useful and engaging they found the session. Which Kirkpatrick level is being measured?","options":["Level 3 — Behaviour","Level 2 — Learning","Level 1 — Reaction","Level 4 — Results"],"answer":2,"explanation":"Level 1 measures how participants felt about the training. It is the easiest to collect but says little about whether skills improved.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-119","question":"Three months after a coaching-skills programme, an HR team asks supervisors whether trainees are actually using the new techniques with their teams. Which Kirkpatrick level is this?","options":["Behaviour","Learning","Reaction","Results"],"answer":0,"explanation":"Level 3 checks whether learning has transferred into on-the-job behaviour. Level 2 tests knowledge or skill gained; level 4 measures business outcomes.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-120","question":"Candidates' scores on a reasoning test taken at hiring are later found to correlate strongly with their performance ratings after a year. This shows that the test has good:","options":["Test–retest reliability","Predictive (criterion-related) validity","Face validity","Inter-rater reliability"],"answer":1,"explanation":"Predictive validity is the extent to which test scores forecast a later criterion such as job performance.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-121","question":"A personality test given to the same group twice, a month apart, produces nearly identical scores. This indicates high:","options":["Test–retest reliability","Predictive validity","Content validity","Construct validity"],"answer":0,"explanation":"Reliability is consistency of measurement. Test–retest reliability checks whether the same people get similar scores on repeated testing.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-122","question":"An appraisal form rates 'customer handling' on a 1–7 scale, with each point described by a specific example of behaviour, such as \"Listens fully and resolves the complaint on the first call\". This method is:","options":["Graphic rating scale","Paired comparison","Forced distribution","Behaviourally anchored rating scale (BARS)"],"answer":3,"explanation":"BARS anchors each scale point with concrete behavioural examples, reducing ambiguity compared with simple graphic scales.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-123","question":"A manager's performance is reviewed using feedback from her boss, peers, direct reports and some internal customers, plus a self-assessment. This is:","options":["Management by objectives","Critical incident method","360-degree feedback","Ranking method"],"answer":2,"explanation":"360-degree feedback collects input from all around the employee, giving a broader picture than a single supervisor's rating.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-124","question":"A supervisor rates almost every team member '3' on a five-point scale, avoiding both high and low ratings. This is the:","options":["Halo effect","Central tendency error","Leniency error","Recency error"],"answer":1,"explanation":"Central tendency error is clustering ratings in the middle, which hides real differences in performance.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-125","question":"A sales manager gives a rep an outstanding annual rating mainly because the rep closed a big deal in the last month, though the first ten months were weak. This is the:","options":["Contrast error","Halo effect","Recency error","Strictness error"],"answer":2,"explanation":"The recency error lets recent events dominate the appraisal of the whole period. Keeping a record of critical incidents through the year reduces it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-126","question":"A friendly manager rates everyone in her team 'exceeds expectations' to avoid disappointing anyone. This is the:","options":["Strictness error","Similar-to-me error","Central tendency error","Leniency error"],"answer":3,"explanation":"Leniency error is rating everyone higher than their performance deserves. It weakens the link between performance and rewards.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-127","question":"A company requires every manager to place 20% of the team in 'top', 70% in 'middle' and 10% in 'bottom' categories. What is the main criticism of this method?","options":["It may force managers to label someone a low performer even when the whole team performs well, hurting morale and collaboration","It allows managers to rate everyone highly","It takes too long to complete","It relies only on self-assessment"],"answer":0,"explanation":"Forced distribution counters leniency and central tendency, but in small or uniformly strong teams it creates artificial losers and can damage teamwork.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-128","question":"A training programme costs ₹12 lakh and produces measurable monetary benefits of ₹18 lakh. What is its ROI using the Phillips formula?","options":["150%","50%","66.7%","33.3%"],"answer":1,"explanation":"ROI = (benefits − costs) / costs × 100 = (18 − 12) / 12 × 100 = 50%. The benefit–cost ratio is 1.5, which is a different measure.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-129","question":"A company receives 1,250 applications and hires 50 people. What is its selection ratio?","options":["40%","25%","2.5%","4%"],"answer":3,"explanation":"Selection ratio = hires / applicants = 50 / 1,250 = 0.04, or 4%. A low ratio means the firm can be very selective.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-130","question":"A firm needs 20 new hires. Historically 10% of applicants are shortlisted, 50% of those shortlisted attend the interview, 25% of interviewees receive offers and 80% of offers are accepted. How many applications must it attract?","options":["1,000","1,600","2,000","4,000"],"answer":2,"explanation":"Work backwards: offers = 20 / 0.8 = 25; interviewees = 25 / 0.25 = 100; shortlisted = 100 / 0.5 = 200; applicants = 200 / 0.10 = 2,000. This is the recruitment yield pyramid.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-131","question":"Why do structured interviews generally predict job performance better than unstructured interviews?","options":["Every candidate is asked the same job-related questions and scored against agreed criteria, reducing bias and inconsistency","They are shorter","They allow interviewers to follow their instincts","They focus on the candidate's personal background"],"answer":0,"explanation":"Standardised, job-related questions with scoring guides make comparisons fair and reduce first-impression and similar-to-me biases.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-132","question":"Management-trainee candidates spend two days on an in-basket exercise, a group discussion, a case presentation and a role-play, observed by several trained assessors. This selection method is:","options":["A realistic job preview","An assessment centre","A stress interview","A probation period"],"answer":1,"explanation":"Assessment centres use multiple exercises and multiple assessors to evaluate candidates on job-relevant competencies.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-133","question":"Match each Kirkpatrick level with the evidence an HR team might collect.\nA. Reaction  B. Learning  C. Behaviour  D. Results\n1. Fall in customer complaints in the trainees' branches\n2. Post-training quiz scores compared with pre-training scores\n3. End-of-session satisfaction ratings\n4. Supervisors observing trainees using the new process on the job","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"Reaction = satisfaction; learning = knowledge or skill gain (pre/post test); behaviour = on-the-job application; results = business outcomes.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-134","question":"A firm spends ₹10 lakh to train 40 sales reps. Afterwards each rep's monthly sales rise by ₹50,000 at a 20% gross margin, sustained for 6 months. HR estimates that 50% of the rise is due to the training. What is the training ROI?","options":["120%","140%","50%","20%"],"answer":3,"explanation":"Benefit = 40 × 50,000 × 0.20 × 6 × 0.5 = ₹12 lakh. ROI = (12 − 10) / 10 = 20%. Ignoring the 50% attribution gives ₹24 lakh and 140%.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-135","question":"A bank gives its loan officers authority to approve loans up to a limit, plan their own schedules and check their own work, instead of just processing files. This is:","options":["Job rotation","Job enlargement","Job enrichment","Job simplification"],"answer":2,"explanation":"Job enrichment adds vertical responsibility — planning, control and decision-making. Job enlargement adds more tasks at the same level; rotation moves people between jobs.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-136","question":"In Hackman and Oldham's model, Motivating Potential Score = [(skill variety + task identity + task significance) / 3] × autonomy × feedback. A job scores 5, 4 and 6 on the first three, 3 on autonomy and 4 on feedback. What is its MPS?","options":["180","60","22","20"],"answer":1,"explanation":"Average of the first three = (5 + 4 + 6) / 3 = 5. MPS = 5 × 3 × 4 = 60. Forgetting to divide by 3 gives 180. Because autonomy and feedback multiply, a zero on either makes MPS zero.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-137","question":"Assertion (A): An unstructured interview may have low validity even when the interviewer is experienced.\nReason (R): Unstructured interviews are inconsistent across candidates and prone to biases such as first impressions and similar-to-me effects.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Experience does not remove the inconsistency and bias built into unstructured interviews, and those flaws are what lower validity. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-138","question":"Consider these statements about appraisal methods:\nI. Forced distribution counters leniency and central tendency errors.\nII. BARS is quick and cheap to develop.\nIII. 360-degree feedback gives a broader view, but raters often need anonymity to be candid.\nWhich are correct?","options":["I only","I, II and III","II and III only","I and III only"],"answer":3,"explanation":"I and III are correct. BARS is time-consuming and costly to develop because behavioural anchors must be collected and validated for each job, so II is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-139","question":"Match each rating error with an example.\nA. Halo  B. Leniency  C. Central tendency  D. Similar-to-me\n1. Rating everyone 'average' to avoid difficult conversations\n2. Rating a candidate highly because he went to the same college as the rater\n3. Rating all team members 'excellent'\n4. Rating someone high on all criteria because she is very punctual","options":["A-4, B-1, C-3, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-2, B-3, C-1, D-4"],"answer":2,"explanation":"Halo = one trait colours all ratings; leniency = everyone rated high; central tendency = everyone rated in the middle; similar-to-me = favouring people like oneself.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-140","question":"A data-entry firm tests candidates by having them enter a sample of real forms within a time limit. Because the test samples the actual tasks of the job, it has high:","options":["Content validity","Predictive validity only","Test–retest reliability","Construct validity"],"answer":0,"explanation":"Content validity is the degree to which a test samples the knowledge and tasks actually required by the job. Work-sample tests are the classic example.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-141","question":"A call-centre firm with high first-month attrition starts showing candidates honest videos of difficult customer calls, night shifts and strict monitoring before they accept offers. What is this practice and its main purpose?","options":["Psychometric testing — to measure personality","An assessment centre — to test skills","Employer branding — to attract more applicants","A realistic job preview — to reduce early turnover by aligning expectations"],"answer":3,"explanation":"Realistic job previews present both positives and negatives, so candidates who would be unhappy self-select out and those who join have realistic expectations.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-142","question":"An HR team compares an individual employee's current skills with the skills her role requires, to decide whether she needs training. This stage of training needs analysis is:","options":["Person analysis","Task analysis","Organisational analysis","Cost–benefit analysis"],"answer":0,"explanation":"Needs analysis has three levels: organisational (where training is needed), task (what the job requires) and person (who needs training and in what).","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-143","question":"On a new hire's first week, the company introduces her to colleagues, explains policies and culture and shows her how her role fits the business. This process is called:","options":["Placement","Job rotation","Induction (onboarding)","Socialisation into retirement"],"answer":2,"explanation":"Induction or onboarding helps new employees settle in, understand the organisation and become productive faster, reducing early turnover.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-144","question":"A company with an average headcount of 300 had 30 employees leave during the year. What is its annual attrition rate?","options":["3%","10%","9.1%","30%"],"answer":1,"explanation":"Attrition rate = separations / average headcount × 100 = 30 / 300 × 100 = 10%.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-145","question":"A firm spent ₹12 lakh in total on recruitment last year and made 40 hires. What was its cost per hire?","options":["₹3,000","₹30,000","₹48,000","₹3,00,000"],"answer":1,"explanation":"Cost per hire = total recruiting cost / number of hires = 12,00,000 / 40 = ₹30,000.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-146","question":"Which of these is a form of variable pay?","options":["Basic salary","House rent allowance","Fixed monthly conveyance allowance","Sales commission"],"answer":3,"explanation":"Variable pay changes with performance or results — commissions, bonuses, incentives. Basic pay and fixed allowances do not vary with output.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-147","question":"A firm started the year with 480 employees and ended with 520. During the year 60 employees left. Using average headcount, what is the attrition rate?","options":["11.5%","12.5%","12%","10%"],"answer":2,"explanation":"Average headcount = (480 + 520) / 2 = 500. Attrition = 60 / 500 = 12%. Dividing by the opening figure gives 12.5%; by the closing figure, 11.5%.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-148","question":"A unit has 200 employees and 25 working days in a month. In that month 400 person-days were lost to unplanned absence. What is the absenteeism rate?","options":["2%","8%","16%","4%"],"answer":1,"explanation":"Absenteeism = person-days lost / (employees × working days) × 100 = 400 / (200 × 25) × 100 = 8%.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-149","question":"An employee earns ₹54,000 a month. The midpoint of her pay range is ₹60,000. What is her compa-ratio?","options":["0.54","1.11","0.90","1.00"],"answer":2,"explanation":"Compa-ratio = actual pay / range midpoint = 54,000 / 60,000 = 0.90. Below 1.0 means she is paid below the midpoint of her grade.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-150","question":"To decide pay grades, a company scores each job on factors such as skill, effort, responsibility and working conditions, and adds up the points. Which job-evaluation method is this?","options":["Ranking method","Job classification","Market pricing","Point (factor) method"],"answer":3,"explanation":"The point method assigns points to compensable factors and totals them, giving a quantitative measure of each job's relative worth.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-151","question":"An HR team buys salary-survey data to check whether its pay for data analysts matches what other employers in the city pay. Which pay goal does this address?","options":["External competitiveness","Internal equity","Individual equity","Procedural justice"],"answer":0,"explanation":"External competitiveness compares pay with the market. Internal equity is about fair pay relationships between jobs within the firm.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-152","question":"A firm records 15 separations in one quarter against an average headcount of 250. If this rate continued, what would the annualised attrition rate be (simple, not compounded)?","options":["6%","24%","15%","12%"],"answer":1,"explanation":"Quarterly attrition = 15 / 250 = 6%. Annualised = 6% × 4 = 24%.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-153","question":"In a year a firm spends ₹6 lakh on agency fees and ₹2 lakh on job ads (external costs), plus ₹4 lakh of recruiter salaries, ₹1 lakh of referral bonuses and ₹1 lakh of managers' interview time (internal costs). It makes 35 hires. What is its cost per hire?","options":["₹22,857","₹34,286","₹28,571","₹40,000"],"answer":3,"explanation":"Total cost = 8 + 6 = ₹14 lakh. Cost per hire = 14,00,000 / 35 = ₹40,000. Counting only external costs gives ₹22,857, understating the true cost.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-154","question":"A firm with an average headcount of 400 had 40 separations: 28 resignations, 8 terminations and 4 retirements. What is its voluntary attrition rate?","options":["10%","9%","7%","8%"],"answer":2,"explanation":"Voluntary attrition counts only employee-initiated exits: 28 / 400 = 7%. Total attrition is 10%; terminations and retirements are usually tracked separately.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-155","question":"The Bradford factor scores absence as S² × D, where S is the number of separate spells and D the total days absent. Employee A had six one-day absences; Employee B had a single six-day absence. What are their scores?","options":["A = 216, B = 6","A = 36, B = 36","A = 6, B = 216","A = 72, B = 12"],"answer":0,"explanation":"A: 6² × 6 = 216. B: 1² × 6 = 6. Both missed six days, but the Bradford factor flags frequent short absences as more disruptive.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-156","question":"A company hired 80 people last year; 20 of them left within twelve months of joining. What is its first-year (new-hire) retention rate?","options":["25%","75%","80%","20%"],"answer":1,"explanation":"New-hire retention = hires still employed after a year / total hires = 60 / 80 = 75%. The first-year attrition rate is 25%.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-157","question":"A company earns ₹240 crore in revenue with 1,600 employees. What is its revenue per employee?","options":["₹15 lakh","₹1.5 lakh","₹150 lakh","₹6.7 lakh"],"answer":0,"explanation":"240 crore / 1,600 = ₹15 lakh per employee. Revenue per employee is a broad productivity measure, best compared across firms in the same industry.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-158","question":"A recruiting team made 45 offers last quarter and 36 were accepted. What is the offer-acceptance rate?","options":["36%","125%","20%","80%"],"answer":3,"explanation":"Offer-acceptance rate = offers accepted / offers made = 36 / 45 = 80%. A low rate can signal uncompetitive pay or a poor candidate experience.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-159","question":"A firm loses 60 employees a year. Replacing each one costs about 50% of the average annual salary of ₹8 lakh. If a retention programme cuts attrition by one-third, roughly how much does it save each year?","options":["₹1.6 crore","₹2.4 crore","₹0.8 crore","₹4.8 crore"],"answer":2,"explanation":"Annual replacement cost = 60 × 0.5 × 8 lakh = ₹2.4 crore. Cutting attrition by a third saves 20 × ₹4 lakh = ₹0.8 crore, before counting the programme's own cost.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-160","question":"Two employees received the same top performance rating. One has a compa-ratio of 0.85 and the other 1.15. Under a typical merit matrix, how should their percentage increases compare?","options":["Both get the same percentage","The employee at 0.85 gets a larger percentage increase","The employee at 1.15 gets a larger percentage increase","Neither gets an increase because ratings are equal"],"answer":1,"explanation":"Merit matrices give larger increases to strong performers who are low in their range, moving them towards the midpoint, and smaller increases to those already high in the range.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-161","question":"A firm has raised starting salaries sharply to attract new graduates, and now some new hires earn almost as much as staff with five years' experience. This problem is called:","options":["Red-circling","Broadbanding","Pay compression","Pay secrecy"],"answer":2,"explanation":"Pay compression occurs when the pay gap between new and experienced employees narrows, which can demotivate long-serving staff.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-162","question":"A company replaces its 18 narrow pay grades with five wide pay bands, giving managers more flexibility to reward growth without promotions. This is:","options":["Job enlargement","Pay compression","Red-circling","Broadbanding"],"answer":3,"explanation":"Broadbanding collapses many grades into a few wide bands, supporting flatter structures and lateral career moves.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-163","question":"An offer has a basic salary of ₹40,000 a month, HRA at 40% of basic, employer PF contribution at 12% of basic, a special allowance of ₹10,000 a month and an annual bonus of ₹60,000. What is the annual cost to company (CTC)?","options":["₹9,09,600","₹8,49,600","₹8,52,000","₹9,60,000"],"answer":0,"explanation":"Monthly = 40,000 + 16,000 + 4,800 + 10,000 = ₹70,800; × 12 = ₹8,49,600; + ₹60,000 bonus = ₹9,09,600. Leaving out the bonus gives ₹8,49,600.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-164","question":"Under the standard formula of 15 days' wages for every completed year of service, with a month treated as 26 working days, what gratuity is due to an employee with 10 years of service whose last drawn basic plus DA is ₹52,000 a month?","options":["₹2,60,000","₹3,00,000","₹2,51,613","₹5,20,000"],"answer":1,"explanation":"Gratuity = last drawn (basic + DA) × 15 / 26 × years = 52,000 × 15 / 26 × 10 = ₹3,00,000. Using 30 days a month gives ₹2,60,000.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-165","question":"A plant has 500 employees, 250 working days a year and an absenteeism rate of 4%. If each day of absence costs ₹2,000 in lost output and cover, what is the annual cost of absenteeism?","options":["₹10 lakh","₹25 lakh","₹40 lakh","₹1 crore"],"answer":3,"explanation":"Days lost = 500 × 250 × 0.04 = 5,000. Cost = 5,000 × ₹2,000 = ₹1 crore.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-166","question":"Assertion (A): For a fast-growing company, calculating attrition on the opening headcount tends to overstate the attrition rate compared with using average headcount.\nReason (R): Average headcount better reflects the number of employees who were exposed to the risk of leaving during the period.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In a growing firm the opening headcount is smaller than the average, so the same separations divided by a smaller base give a higher rate. Average headcount captures everyone who could have left, which is why it is preferred.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-167","question":"Consider these statements about recruitment metrics:\nI. Cost per hire should include internal costs such as recruiter salaries.\nII. A falling time-to-fill always means better hiring quality.\nIII. Quality of hire can be judged from new hires' performance and retention.\nWhich are correct?","options":["II and III only","I, II and III","I and III only","I only"],"answer":2,"explanation":"I and III are correct. Faster hiring can come at the cost of poorer selection, so II is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-168","question":"Under a plant-wide scheme, employees receive a share of the savings whenever labour costs per unit fall below a historical baseline. This type of plan is called:","options":["Gainsharing (e.g. Scanlon-type plan)","Piece-rate pay","Seniority pay","Stock options"],"answer":0,"explanation":"Gainsharing plans share productivity or cost-saving gains with groups of employees, encouraging teamwork and suggestions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-169","question":"A start-up grants employees stock options that vest over four years. What is the main HR objective of this?","options":["To reduce statutory deductions","To meet minimum-wage requirements","To replace basic salary entirely","To align employees' interests with long-term company value and encourage retention"],"answer":3,"explanation":"Vesting over several years rewards staying, and ownership links employees' rewards to company performance.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-170","question":"A company lets each employee choose from a menu of benefits — extra health cover, meal cards, childcare support or additional leave — within a fixed budget. This is a:","options":["Defined-benefit pension plan","Cafeteria (flexible) benefits plan","Gainsharing plan","Piece-rate plan"],"answer":1,"explanation":"Cafeteria plans let employees tailor benefits to their own needs, increasing the value they perceive for the same cost.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-171","question":"A warehouse needs 180 workers present every day. Average absenteeism is 10%. How many workers should be on the rolls?","options":["198","190","200","180"],"answer":2,"explanation":"On-roll staff × 0.90 = 180, so on-roll staff = 180 / 0.9 = 200. Adding 10% to 180 (198) undershoots because the 10% applies to the larger on-roll number.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-172","question":"India consolidated many central labour laws into four labour codes. Which of these is NOT one of them?","options":["Code on Wages","Industrial Relations Code","Code on Social Security","Code on Employee Stock Ownership"],"answer":3,"explanation":"The four codes are the Code on Wages, the Industrial Relations Code, the Code on Social Security, and the Occupational Safety, Health and Working Conditions Code.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-173","question":"Under India's law on prevention of sexual harassment at the workplace (POSH), an employer with 10 or more employees must set up a body to hear complaints. What is it called?","options":["Works Committee","Internal Committee","Grievance Redressal Board","Labour Court"],"answer":1,"explanation":"The POSH Act requires an Internal Committee (earlier called the Internal Complaints Committee) at every workplace with 10 or more employees.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-174","question":"A factory pays women packers less than men doing the same packing work, citing 'tradition'. Which principle in India's wage law does this violate?","options":["Payment of bonus","Equal remuneration for the same work or work of a similar nature, regardless of gender","Minimum notice before a strike","Standing orders"],"answer":1,"explanation":"The Code on Wages prohibits discrimination on the basis of gender in wages for the same work or work of a similar nature.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-175","question":"Union representatives and management meet over several weeks to negotiate wages, working hours and leave for all workers, and then sign a settlement. This process is called:","options":["Collective bargaining","Grievance handling","Domestic enquiry","Job evaluation"],"answer":0,"explanation":"Collective bargaining is negotiation between employers and workers' representatives to agree terms and conditions of employment.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-176","question":"A purchase manager learns that a vendor bidding for a large contract is owned by her brother. What is the most appropriate ethical action?","options":["Evaluate the bid herself but be extra strict","Tell her brother the competitors' prices so the process is fair","Quietly reject the vendor without explanation","Disclose the relationship and step away from the decision"],"answer":3,"explanation":"A conflict of interest should be disclosed and the person should recuse from the decision. Rejecting silently or acting on it secretly both fail transparency.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-177","question":"An employee wants to report that a senior manager is falsifying expense claims, but fears retaliation. Which policy is meant to protect her?","options":["Dress code","Leave policy","Whistle-blower (vigil mechanism) policy","Travel policy"],"answer":2,"explanation":"A whistle-blower or vigil mechanism gives employees a confidential channel to report wrongdoing and protects them from retaliation.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-178","question":"An employee's total monthly remuneration is ₹1,00,000, of which basic pay plus DA is ₹30,000 and allowances excluded from 'wages' make up ₹70,000. Under the Code on Wages rule that excluded components above 50% of total remuneration are added back, what is the 'wage' for statutory purposes?","options":["₹30,000","₹50,000","₹70,000","₹35,000"],"answer":1,"explanation":"Excluded components may be at most 50% (₹50,000). The excess of ₹20,000 is added back: 30,000 + 20,000 = ₹50,000. This tends to raise the base for PF and gratuity.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-179","question":"Consider these statements about fixed-term employment under India's new labour codes:\nI. Fixed-term employees are entitled to the same wages and benefits as permanent employees doing the same or similar work.\nII. Fixed-term employees can become eligible for gratuity on a pro-rata basis without completing five years.\nIII. Fixed-term employees are excluded from all statutory benefits.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. The codes give fixed-term employees parity with permanent staff doing similar work and pro-rata gratuity without the five-year condition, so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-180","question":"What change did the Industrial Relations Code make to the rules on strikes?","options":["It banned strikes in all private establishments","It required notice only in establishments with more than 300 workers","It removed the need for any notice before a strike","It extended the requirement of advance notice before a strike to all industrial establishments, not just public utility services"],"answer":3,"explanation":"Earlier, strike notice was mainly required in public utility services. The IR Code applies the advance-notice requirement to all industrial establishments.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-181","question":"Under the Industrial Relations Code, prior government permission for lay-off, retrenchment or closure is required in industrial establishments employing at least how many workers?","options":["50","100","300","1,000"],"answer":2,"explanation":"The IR Code raised the threshold for prior permission from 100 workers (under the earlier law) to 300 workers, with a provision allowing governments to change it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-182","question":"Which new category of workers was explicitly brought under the social-security framework by India's Code on Social Security?","options":["Gig and platform workers","Civil servants","Armed forces personnel","Company directors"],"answer":0,"explanation":"The Code on Social Security recognises gig workers and platform workers and provides for social-security schemes for them, partly funded by aggregator contributions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-183","question":"Faced with a choice between closing a loss-making unit (300 jobs lost, company saved) and keeping it open (whole company at risk), a manager chooses the option that produces the greatest overall good for the most people. Which ethical approach is she using?","options":["Virtue approach","Rights approach","Justice approach","Utilitarian approach"],"answer":3,"explanation":"The utilitarian approach judges actions by their consequences — the greatest net benefit for the greatest number.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-184","question":"During a tender, a bidding vendor sends an expensive watch to the evaluation manager's home. Under a typical gifts policy, what should the manager do?","options":["Decline or return it and report it as the policy requires","Keep it, since it was sent to his home","Keep it but give the vendor a lower score to compensate","Share it with the team"],"answer":0,"explanation":"Gifts of significant value from parties seeking business create a conflict of interest, especially during a tender. They should be declined or returned and declared.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-185","question":"A supervisor hints to a junior employee that her promotion depends on accepting his personal advances. Which form of sexual harassment is this?","options":["Hostile work environment harassment","Third-party harassment","Quid pro quo harassment","Constructive dismissal"],"answer":2,"explanation":"Quid pro quo ('this for that') harassment makes job benefits conditional on sexual favours. Hostile-environment harassment is unwelcome conduct that creates an intimidating workplace.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-186","question":"Bonuses this year are lower than expected, but employees accept them without much complaint because the criteria were announced in advance, applied consistently and staff could question the results. Which form of organisational justice explains this?","options":["Distributive justice","Procedural justice","Interactional justice","Retributive justice"],"answer":1,"explanation":"Procedural justice is the perceived fairness of the process used to decide outcomes. Fair processes make unfavourable outcomes easier to accept.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-187","question":"An analyst regularly stays back to help new joiners learn the systems and volunteers to organise team events, though neither is part of her job or rewarded formally. This is an example of:","options":["Presenteeism","Social loafing","Role conflict","Organisational citizenship behaviour"],"answer":3,"explanation":"Organisational citizenship behaviour is discretionary behaviour beyond formal role requirements that helps the organisation function.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-188","question":"A firm has 100 junior and 40 senior analysts. Each year 70% of juniors stay junior, 10% are promoted to senior and 20% leave; 85% of seniors stay and 15% leave. Before any external hiring, how many senior analysts will there be next year?","options":["34","44","40","50"],"answer":1,"explanation":"Seniors next year = 40 × 0.85 + 100 × 0.10 = 34 + 10 = 44. This transition-matrix method is Markov analysis, used in HR supply forecasting.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-189","question":"A company has 500 employees and expects to need 520 next year. Annual attrition is expected to be 12%. How many people must it hire during the year?","options":["20","60","80","82"],"answer":2,"explanation":"Staff remaining = 500 × 0.88 = 440. Hires needed = 520 − 440 = 80. Planning only for growth (20) ignores replacement demand.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-190","question":"A high performer was told at joining that she would lead a team within two years. Three years later there is no sign of it, and her commitment and discretionary effort have dropped sharply. What best explains this?","options":["A breach of the psychological contract","Social loafing","The halo effect","Job enlargement"],"answer":0,"explanation":"The psychological contract is the unwritten set of mutual expectations between employer and employee. When the employee sees it as broken, trust, commitment and effort fall.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-191","question":"Assertion (A): Bringing many central labour laws together into four codes was meant to reduce compliance complexity for employers.\nReason (R): The older laws were numerous and overlapping, with different definitions of terms such as 'wages' and 'employee'.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Simplification and uniform definitions were central aims of the codes, because the many overlapping laws with inconsistent definitions made compliance difficult. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-192","question":"Consider these statements about the Internal Committee under India's POSH law:\nI. It is to be headed by a senior woman employee.\nII. It includes an external member from an NGO or someone familiar with issues of sexual harassment.\nIII. It can hear complaints only from permanent employees.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. The law protects any woman at the workplace — including contract staff, trainees, interns and visitors — so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-193","question":"Match each ethical approach with its core question.\nA. Utilitarian  B. Rights  C. Justice  D. Virtue\n1. Are benefits and burdens distributed fairly?\n2. Does the action respect people's entitlements, such as privacy and free consent?\n3. Which action produces the greatest net good?\n4. What would a person of good character do?","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"Utilitarian = consequences; rights = entitlements; justice = fair distribution; virtue = character.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-194","question":"A manager announcing layoffs meets each affected employee privately, explains the reasons honestly and treats them with dignity and respect. Which dimension of organisational justice is she addressing most directly?","options":["Distributive justice","Procedural justice","Restorative justice","Interactional justice"],"answer":3,"explanation":"Interactional justice is about the quality of interpersonal treatment — respect, dignity and honest explanations — when decisions are communicated.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-195","question":"McGregor's 'hot-stove rule' says discipline should be immediate, give advance warning, be consistent and be impersonal. A supervisor ignores lateness by his favourites but punishes others for it. Which element is he violating most clearly?","options":["Immediacy","Advance warning","Consistency and impersonality","Proportionality to output"],"answer":2,"explanation":"Like a hot stove that burns everyone who touches it, discipline should apply the same way to everyone. Favouritism breaks both consistency and impersonality.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-196","question":"In a progressive discipline system, which sequence is usually followed for a repeated, non-serious offence?","options":["Termination → suspension → written warning → oral warning","Oral warning → written warning → suspension → termination","Written warning → oral warning → termination → suspension","Suspension → oral warning → written warning → termination"],"answer":1,"explanation":"Progressive discipline increases penalties step by step, giving the employee chances to correct behaviour before dismissal. Serious misconduct may skip steps.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-197","question":"A company plans to employ 600 workers next year and keeps a ratio of one supervisor to every 12 workers. It has 40 supervisors and expects none to leave. How many more supervisors does it need?","options":["12","50","10","8"],"answer":2,"explanation":"Required supervisors = 600 / 12 = 50. Additional needed = 50 − 40 = 10. This is the ratio-trend method of HR demand forecasting.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-198","question":"In a domestic enquiry into alleged misconduct, the manager who filed the complaint is also appointed as the enquiry officer. Which principle of natural justice is violated?","options":["The right to be heard","The right to appeal","Punishment must be proportionate","No one should be a judge in their own cause"],"answer":3,"explanation":"Natural justice requires an unbiased decision-maker (nemo judex in causa sua) and a fair hearing. A complainant judging his own complaint fails the first principle.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-199","question":"Assertion (A): A well-written code of ethics, on its own, may not prevent misconduct in an organisation.\nReason (R): Employee behaviour is shaped heavily by incentives, leaders' example and consistent enforcement, not only by written rules.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Codes work only when leaders model them, incentives do not reward violations and breaches are enforced. R explains why a code alone is not enough.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-200","question":"What is the main purpose of an exit interview?","options":["To understand why employees leave and identify patterns the organisation can fix","To persuade the employee to withdraw the resignation at any cost","To recover company property only","To calculate the employee's final settlement"],"answer":0,"explanation":"Exit interviews gather honest feedback on reasons for leaving — manager, pay, growth, culture — so HR can spot and fix retention problems.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
];

export default questions;
